import math

def get_prime_factors(n):
    factors = set()
    d = 2
    temp = n
    while d * d <= temp:
        if temp % d == 0:
            factors.add(d)
            while temp % d == 0:
                temp //= d
        d += 1
    if temp > 1:
        factors.add(temp)
    return list(factors)

def omega(n):
    return len(get_prime_factors(n))

def sigma(n):
    if n == 1:
        return 1
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    sum_div = 1
    for p, k in factors.items():
        sum_div *= (p**(k+1) - 1) // (p - 1)
    return sum_div

def is_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def find_square_divisors(n):
    divs = get_divisors(n)
    square_divs = [d for d in divs if math.isqrt(d)**2 == d]
    return square_divs

candidates_found = []

# Search up to m < 500
for m in range(1, 500):
    if m <= 1:
        continue

    # 1. Check omega(m) >= 3
    if omega(m) < 3:
        continue

    # 2. Check sigma(m) is a perfect square
    sigma_m = sigma(m)
    if not is_square(sigma_m):
        continue

    # Candidate found based on necessary conditions
    candidates_found.append(m)

print("--- Candidates satisfying omega(m) >= 3 and sigma(m) = K^2 (m < 500) ---")
print(candidates_found)

print("\n--- Testing S2 = a1 + a2 condition for candidates ---")
results = {}
for m in candidates_found:
    divs = get_divisors(m)
    sq_divs = find_square_divisors(m)

    is_S2_possible = False

    # Iterate through possible a1 (must be a square divisor)
    for a1 in sq_divs:

        # Find remaining divisors excluding a1
        remaining_divs = [d for d in divs if d != a1]

        # Test initial constraint S2 = a1 + a2 = K^2
        for a2 in remaining_divs:
            S2 = a1 + a2
            if is_square(S2):
                # We found at least one combination (a1, a2) that works for S2
                is_S2_possible = True
                break
        if is_S2_possible:
            break

    if is_S2_possible:
        results[m] = "S2 possible (needs further permutation check)"
    else:
        results[m] = "S2 impossible (failed)"

print("\n--- S2 Test Results ---")
for m, status in results.items():
    print(f"m = {m}: {status}")
